import express from 'express';

const app = express();
app.use(express.json());

// Helper function to check if a URL is external
function isExternalURL(url) {
    try {
        const parsedUrl = new URL(url);
        return parsedUrl.hostname !== 'localhost' && parsedUrl.hostname !== '127.0.0.1';
    } catch {
        return false;
    }
}

// Simulated server action reducer with the bug
function serverActionReducer(state, action) {
    const mutable = {};
    let redirectLocation = action.redirectLocation;
    let redirectType = action.redirectType;
    let actionResult = action.result;

    return new Promise((resolve, reject) => {
        if (redirectLocation !== undefined) {
            const resolvedRedirectType = redirectType || 'push';
            const redirectHref = redirectLocation;
            const redirectError = new Error(`Redirect to ${redirectHref}`);
            redirectError.type = resolvedRedirectType;

            // BUG: No distinction between internal and external URLs
            // This causes external redirects to be handled incorrectly
            reject(redirectError);

            // Simulate state update for pending push
            const pendingPush = redirectType !== 'replace';
            state.pushRef = { pendingPush };
            mutable.pendingPush = pendingPush;
        } else {
            resolve(actionResult);
        }
    });
}

// Route to test the reducer
app.post('/api/action', async (req, res) => {
    try {
        const { redirectLocation, redirectType, result } = req.body;
        const state = { pushRef: {} };
        const action = { redirectLocation, redirectType, result };

        const actionResult = await serverActionReducer(state, action);
        res.json({ success: true, data: actionResult, state });
    } catch (error) {
        res.status(500).json({ success: false, error: error.message });
    }
});

const PORT = 3000;
app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});

export { serverActionReducer, isExternalURL };

