import { serverActionReducer, isExternalURL } from './server.js';

async function runTests() {
    console.log('Running tests...');
    let passed = 0;
    let failed = 0;

    // Test 1: Internal redirect should work
    try {
        const state = { pushRef: {} };
        const action = { redirectLocation: '/profile', redirectType: 'push', result: null };
        await serverActionReducer(state, action);
        console.log('Test 1 FAILED: Internal redirect should reject with error');
        failed++;
    } catch (error) {
        if (error.message.includes('Redirect to /profile') && error.type === 'push') {
            console.log('Test 1 PASSED: Internal redirect handled');
            passed++;
        } else {
            console.log('Test 1 FAILED: Unexpected error', error);
            failed++;
        }
    }

    // Test 2: External redirect should trigger MPA navigation
    try {
        const state = { pushRef: {} };
        const action = { redirectLocation: 'https://twitter.com', redirectType: 'push', result: null };
        await serverActionReducer(state, action);
        console.log('Test 2 FAILED: External redirect should reject with error and handle MPA');
        failed++;
    } catch (error) {
        if (error.message.includes('Redirect to https://twitter.com') && error.type === 'push') {
            // Check if external URL detection is used
            if (isExternalURL('https://twitter.com')) {
                console.log('Test 2 PASSED: External redirect detected and handled');
                passed++;
            } else {
                console.log('Test 2 FAILED: External URL not detected');
                failed++;
            }
        } else {
            console.log('Test 2 FAILED: Unexpected error', error);
            failed++;
        }
    }

    // Test 3: No redirect should resolve with result
    try {
        const state = { pushRef: {} };
        const action = { redirectLocation: undefined, redirectType: null, result: 'success' };
        const result = await serverActionReducer(state, action);
        if (result === 'success') {
            console.log('Test 3 PASSED: No redirect resolves correctly');
            passed++;
        } else {
            console.log('Test 3 FAILED: Incorrect result', result);
            failed++;
        }
    } catch (error) {
        console.log('Test 3 FAILED: Unexpected error', error);
        failed++;
    }

    // Test 4: Redirect with replace type
    try {
        const state = { pushRef: {} };
        const action = { redirectLocation: '/settings', redirectType: 'replace', result: null };
        await serverActionReducer(state, action);
        console.log('Test 4 FAILED: Replace redirect should reject with error');
        failed++;
    } catch (error) {
        if (error.message.includes('Redirect to /settings') && error.type === 'replace') {
            console.log('Test 4 PASSED: Replace redirect handled');
            passed++;
        } else {
            console.log('Test 4 FAILED: Unexpected error', error);
            failed++;
        }
    }

    console.log(`\nTotal: ${passed} passed, ${failed} failed`);
    if (failed === 0) {
        console.log('All tests passed!');
    } else {
        console.log('Some tests failed. Fix the bug and try again.');
        process.exit(1);
    }
}

runTests();
